#include <vector>
#include <unordered_map>
using namespace std;

class Solution {
public:
    vector<int> findPair(vector<int>& nums, int target) {
        unordered_map<int, int> map;

        for (int i = 0; i < nums.size(); i++) {
            int complement = target - nums[i];

            if (map.count(complement)) {
                return { map[complement], i };
            }

            map[nums[i]] = i;
        }

        return { -1, -1 };
    }
};
